    VALUES ('71a8e2c2-d3d8-43ff-a40b-a8f3148564ee', N'Nhà máy nước Yên Phụ', N'Nhà máy nước Yên Phụ, Hà Nội', 20.920571, 105.85224);
ELSE
    UPDATE bus_stops SET address = N'Nhà máy nước Yên Phụ, Hà Nội', latitude = 20.920571, longitude = 105.85224 WHERE stop_name = N'Nhà máy nước Yên Phụ';

