INSERT INTO schedules (id, route_id, bus_id, departure_time, average_speed_kmh, days_of_week)
SELECT '1a6578c0-56de-4538-a155-dc0106c568fb', r.id, NULL, '05:00:00', 22.5, 'MON-SUN'
FROM bus_routes r
WHERE r.route_code = '01'
AND NOT EXISTS (SELECT 1 FROM schedules sc2 WHERE sc2.route_id = r.id AND sc2.departure_time = '05:00:00');

INSERT INTO schedules (id, route_id, bus_id, departure_time, average_speed_kmh, days_of_week)
SELECT 'ead2c935-ab67-4d69-abb7-5957345f1f20', r.id, NULL, '05:20:00', 22.5, 'MON-SUN'
